namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{1,3}\d{6,9}$", ErrorMessage = "Student ID must be 1-3 uppercase letters followed by 6-9 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore the foundations of computing, software engineering, and emerging technologies." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study abstract structures, quantitative reasoning, and mathematical modeling." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Investigate the fundamental laws governing matter, energy, and the universe." },
            new() { Id = 4, Name = "English", Code = "ENGL", Description = "Develop critical reading, writing, and analytical skills through literature and composition." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Examine the people, events, and ideas that have shaped civilizations across time." }
        };

        _instructors = new List<Instructor>
        {
            // CS
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in algorithms and machine learning. She has published over 40 papers in top-tier conferences and holds two patents in natural language processing.", Email = "schen@university.edu" },
