@page "/courses"
@rendermode InteractiveServer
@inject CatalogService Catalog
@inject NavigationManager Navigation

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name (@dept.Code)</option>
            }
        </select>
    </div>
</div>

@{
    var filteredCourses = Catalog.GetCourses(searchTerm, selectedDepartmentId > 0 ? selectedDepartmentId : null);
}

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead class="table-dark">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in filteredCourses)
            {
                var dept = Catalog.GetDepartmentForCourse(course.Id);
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private IReadOnlyList<Department> departments = [];
    private string? searchTerm;
    private int selectedDepartmentId;

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        if (DepartmentId.HasValue)
        {
            selectedDepartmentId = DepartmentId.Value;
        }
    }
}

@page "/courses/{Id:int}"
@inject CatalogService Catalog

<PageTitle>Course Detail</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">
        <h4>Course Not Found</h4>
        <p>The requested course could not be found.</p>
        <a href="courses" class="btn btn-primary">Back to Course Catalog</a>
    </div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Course Description</h5>
                    <p>@course.Description</p>

                    <div class="row mt-3">
                        <div class="col-sm-6">
                            <p><strong>Credits:</strong> @course.Credits</p>
                            <p><strong>Schedule:</strong> @course.Schedule</p>
                        </div>
                        <div class="col-sm-6">
                            <p><strong>Location:</strong> @course.Location</p>
                            @if (department is not null)
                            {
                                <p><strong>Department:</strong> <a href="courses?departmentId=@department.Id">@department.Name</a></p>
                            }
                        </div>
                    </div>
                </div>
            </div>

            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Enrollment Status</h5>
                    @{
                        var pct = course.MaxEnrollment > 0 ? (int)(100.0 * course.CurrentEnrollment / course.MaxEnrollment) : 0;
                        var barClass = pct >= 90 ? "bg-danger" : pct >= 70 ? "bg-warning" : "bg-success";
                    }
                    <p>@course.CurrentEnrollment of @course.MaxEnrollment seats filled</p>
                    <div class="progress" role="progressbar">
                        <div class="progress-bar @barClass" style="width: @(pct)%">@pct%</div>
                    </div>
                </div>
            </div>

            <a href="enroll?courseId=@course.Id" class="btn btn-primary btn-lg">Enroll in This Course</a>
            <a href="courses" class="btn btn-outline-secondary btn-lg ms-2">Back to Catalog</a>
        </div>

        <div class="col-md-4">
            @if (instructor is not null)
            {
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6 class="card-subtitle mb-2 text-body-secondary">@instructor.Name</h6>
                        <p class="mb-1"><em>@instructor.Title</em></p>
                        <p>@instructor.Bio</p>
                        <p><strong>Email:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            department = Catalog.GetDepartmentForCourse(course.Id);
            instructor = Catalog.GetInstructorForCourse(course.Id);
        }
    }
}

@page "/enroll"
@inject CatalogService Catalog
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

<div class="row">
    <div class="col-md-8 col-lg-6">
        <EditForm Model="Model" OnValidSubmit="HandleValidSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Student Name</label>
                <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                <ValidationMessage For="() => Model.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., CS123456" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment</button>
            <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleValidSubmit()
    {
        Catalog.SubmitEnrollment(Model);
        Navigation.NavigateTo("/enrollment-confirmation");
    }
}

